CREATE OR REPLACE FUNCTION public.resolve_event_coverage(_code text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT jsonb_build_object('event_id',e.id,'org_slug',o.slug,'name',e.name,'mode',e.coverage_mode,'store_ids',COALESCE((SELECT jsonb_agg(s) FROM public.event_scope_stores(e.org_id,e.coverage_mode,e.covered_store_ids,e.region_id,e.store_id) s),'[]'::jsonb),'stores',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',d.id,'name',d.name,'brand',d.brand,'city',d.city,'state',d.state)) FROM public.dealerships d WHERE d.id IN (SELECT public.event_scope_stores(e.org_id,e.coverage_mode,e.covered_store_ids,e.region_id,e.store_id))),'[]'::jsonb)) FROM public.recruiting_events e JOIN public.organizations o ON o.id=e.org_id WHERE e.code=upper(btrim(_code)) AND e.is_active
$$;